-- Synthetic finance. Every row is generated by SeedRunner; nothing here is real.

CREATE TABLE department (
    id    NUMBER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    code  VARCHAR2(16) NOT NULL,
    name  VARCHAR2(80) NOT NULL,
    CONSTRAINT uq_department_code UNIQUE (code)
);

CREATE TABLE employee (
    id             NUMBER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    department_id  NUMBER        NOT NULL,
    full_name      VARCHAR2(120) NOT NULL,
    role           VARCHAR2(20)  NOT NULL,
    email          VARCHAR2(120) NOT NULL,
    salary_mad     NUMBER(10,2)  NOT NULL,
    hired_on       DATE          NOT NULL,
    CONSTRAINT fk_employee_department FOREIGN KEY (department_id) REFERENCES department (id),
    CONSTRAINT ck_employee_role CHECK (role IN ('FINANCE_MANAGER', 'ACCOUNTANT', 'CLERK', 'HR', 'ADMIN')),
    CONSTRAINT uq_employee_email UNIQUE (email)
);

CREATE TABLE supplier (
    id             NUMBER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    department_id  NUMBER        NOT NULL,
    manager_id      NUMBER        NOT NULL,
    full_name      VARCHAR2(120) NOT NULL,
    tax_id    VARCHAR2(12)  NOT NULL,
    founded_on     DATE          NOT NULL,
    phone          VARCHAR2(20)  NOT NULL,
    address        VARCHAR2(200) NOT NULL,
    iban      VARCHAR2(200) NOT NULL,
    onboarded_on    DATE          NOT NULL,
    CONSTRAINT fk_supplier_department FOREIGN KEY (department_id) REFERENCES department (id),
    CONSTRAINT fk_supplier_manager FOREIGN KEY (manager_id) REFERENCES employee (id),
    CONSTRAINT uq_supplier_tax_id UNIQUE (tax_id)
);
CREATE INDEX ix_supplier_department ON supplier (department_id);
CREATE INDEX ix_supplier_manager ON supplier (manager_id);

CREATE TABLE invoice (
    id             NUMBER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    supplier_id     NUMBER        NOT NULL,
    manager_id      NUMBER        NOT NULL,
    department_id  NUMBER        NOT NULL,
    due_at   TIMESTAMP     NOT NULL,
    amount_mad     NUMBER(12,2)  NOT NULL,
    status         VARCHAR2(12)  NOT NULL,
    notes          VARCHAR2(300),
    CONSTRAINT fk_invoice_supplier FOREIGN KEY (supplier_id) REFERENCES supplier (id),
    CONSTRAINT fk_invoice_manager FOREIGN KEY (manager_id) REFERENCES employee (id),
    CONSTRAINT fk_invoice_department FOREIGN KEY (department_id) REFERENCES department (id),
    CONSTRAINT ck_invoice_status CHECK (status IN ('PENDING', 'PAID', 'CANCELLED'))
);
CREATE INDEX ix_invoice_dept_day ON invoice (department_id, due_at);

CREATE TABLE document (
    id             NUMBER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    department_id  NUMBER        NOT NULL,
    title          VARCHAR2(160) NOT NULL,
    body           CLOB          NOT NULL,
    uploaded_on    DATE          NOT NULL,
    CONSTRAINT fk_document_department FOREIGN KEY (department_id) REFERENCES department (id)
);
